  testq %rdi, %rdi
  js .Llen0
  movabsq $2097152, %rdx
  cmpq %rdx, %rdi
  jg .Llen0
  leaq mjz_alen(%rip), %rdx
  movq (%rdx,%rdi,8), %rax
  ret
.Llen0:
  xorl %eax, %eax
  ret
# int64 mjz_load(int64 h, int64 i): TRAPs unless 0 <= i < len[h]
mjz_load:
