  cmpq %rcx, %rsi
  jge mjz_trap
  leaq mjz_arena(%rip), %rdx
  addq %rdi, %rsi
  movq (%rdx,%rsi,8), %rax
  ret
# void mjz_store(int64 h, int64 i, int64 v)
mjz_store:
