# int64 mjz_input(void): scanf into stack scratch; 0 on EOF/failure
mjz_input:
  pushq %rbx
  subq $16, %rsp
  leaq .Lscan(%rip), %rdi
  movq $0, (%rsp)
  movq %rsp, %rsi
  xorl %eax, %eax
  call scanf
  movq (%rsp), %rax
  addq $16, %rsp
  popq %rbx
  ret
  .section .rodata
.Lfmt:
  .string "%lld\n"
.Ltraps:
